// Package schema renders the JSON Schema of policy files from the spec the
// modules validate them with. The files in schemas/ are generated by
// make code-generate and checked by make code-lint.
package schema

import (
	"encoding/json"

	"github.com/Kuzmenko-Pavel/gitlab-repopolicy/internal/modules/branch"
	"github.com/Kuzmenko-Pavel/gitlab-repopolicy/internal/modules/commit"
	"github.com/Kuzmenko-Pavel/gitlab-repopolicy/internal/modules/path"
	"github.com/Kuzmenko-Pavel/gitlab-repopolicy/internal/modules/tag"
	"github.com/Kuzmenko-Pavel/gitlab-repopolicy/internal/spec"
)

// Draft is the JSON Schema dialect of the generated files.
const Draft = "https://json-schema.org/draft/2020-12/schema"

// Files returns the documents of schemas/ by file name.
func Files() (map[string][]byte, error) {
	out := map[string][]byte{}
	for _, f := range []struct {
		name, title string
		spec        *spec.Spec
	}{
		{"pathpolicy", path.File, path.Spec},
		{"commitpolicy", commit.File, commit.Spec},
		{"tagpolicy", tag.File, tag.Spec},
		{"branchpolicy", branch.File, branch.Spec},
	} {
		doc, err := Document(f.title, f.spec)
		if err != nil {
			return nil, err
		}
		out[f.name+".schema.json"] = doc
	}
	return out, nil
}

// Document renders the schema of s as indented JSON with a trailing newline.
func Document(title string, s *spec.Spec) ([]byte, error) {
	root := node(s)
	root["$schema"] = Draft
	root["title"] = title
	data, err := json.MarshalIndent(root, "", "  ")
	if err != nil {
		return nil, err
	}
	return append(data, '\n'), nil
}

func node(s *spec.Spec) map[string]any {
	out := map[string]any{}
	switch s.Type {
	case spec.Any:
		if len(s.OneOf) > 0 {
			alts := make([]any, 0, len(s.OneOf))
			for _, a := range s.OneOf {
				alts = append(alts, node(a))
			}
			out["oneOf"] = alts
		}
	case spec.Object:
		props := map[string]any{}
		var required []string
		for _, f := range s.Fields {
			p := node(f.Spec)
			props[f.Name] = p
			if f.Required {
				required = append(required, f.Name)
			}
			// The schema describes a file, where a rule may override a preset
			// rule partly; only the result of merging must have the field.
			if f.AfterMerge {
				desc := "Required after merging with presets."
				if d, ok := p["description"].(string); ok {
					desc += " " + d
				}
				p["description"] = desc
			}
		}
		// An Open object is closed for editors too: an unknown key is valid
		// only on the anchor and rejected in a new version.
		out["type"], out["properties"], out["additionalProperties"] = "object", props, false
		if len(required) > 0 {
			out["required"] = required
		}
	case spec.Array:
		out["type"], out["items"] = "array", node(s.Items)
		bounds(out, "minItems", s.MinItems, "maxItems", s.MaxItems)
		if s.Unique {
			out["uniqueItems"] = true
		}
		if s.Named != "" {
			out["x-repopolicy-check"] = "unique-names"
		}
	case spec.Dict:
		out["type"], out["additionalProperties"] = "object", node(s.Values)
		bounds(out, "minProperties", s.MinItems, "maxProperties", s.MaxItems)
		if s.KeyPattern != "" {
			out["propertyNames"] = map[string]any{"pattern": s.KeyPattern}
		}
	case spec.String:
		out["type"] = "string"
		bounds(out, "minLength", s.MinLength, "maxLength", s.MaxLength)
		if s.Pattern != "" {
			out["pattern"] = s.Pattern
		}
		if len(s.Enum) > 0 {
			out["enum"] = s.Enum
		}
	case spec.Integer:
		out["type"] = "integer"
		if s.Const != 0 {
			out["const"] = s.Const
		}
		if s.Maximum != 0 {
			out["minimum"], out["maximum"] = s.Minimum, s.Maximum
		}
	case spec.Boolean:
		out["type"] = "boolean"
	}
	if s.Desc != "" {
		out["description"] = s.Desc
	}
	if s.Check != "" {
		out["x-repopolicy-check"] = s.Check
	}
	if s.Nullable {
		nullable(out)
	}
	return out
}

// nullable lets a node be null: a file removes what a preset sets.
func nullable(out map[string]any) {
	if t, ok := out["type"].(string); ok {
		out["type"] = []string{t, "null"}
		return
	}
	if alts, ok := out["oneOf"].([]any); ok {
		out["oneOf"] = append(alts, map[string]any{"type": "null"})
	}
}

func bounds(out map[string]any, minKey string, low int, maxKey string, high int) {
	if low > 0 {
		out[minKey] = low
	}
	if high > 0 {
		out[maxKey] = high
	}
}
